local json = require("dkjson")
local lfs = require("lfs")
local pl_path = require("pl.path")

local api = require("kcl_lib.raw_api")

-- Cross-language consistency runner: executes the hermetic cases from
-- `tests/consistency/cases.json` (generated by
-- `tests/consistency/generate_cases.py`) and asserts the same golden
-- expectations as the python/nodejs/go/java/dotnet runners.
--
-- Nothing about a case is hardcoded here. The name, the arguments and the
-- expected values all come from the shared manifest, and the projections
-- below only say how to read an answer out of `lua-protobuf`'s decoded
-- message -- regenerating the golden file turns a real binding into a real
-- red, and adding a case to it turns into a red here too (see the coverage
-- guard at the bottom of the file).
--
-- Run it with:
--
--     luarocks test ./*.rockspec
--
-- `spec/` is two levels below the repository root, which is also two levels
-- above `tests/consistency/cases.json`. Resolve against this file rather than
-- the working directory so the suite behaves the same whether busted is
-- invoked from `lua/` or from the repository root.

local SPEC_DIR = pl_path.dirname(
  debug.getinfo(1, "S").source:gsub("^@", "")
)
local REPO_ROOT = pl_path.abspath(pl_path.join(SPEC_DIR, "..", ".."))
local CASES_JSON = pl_path.join(REPO_ROOT, "tests", "consistency", "cases.json")
local TESTDATA = pl_path.join(REPO_ROOT, "tests", "consistency", "testdata")

---Read `node[key]`, falling back to `default` when the key is absent or JSON
---`null` (`dkjson.null`).
---@param node any
---@param key string
---@param default any
---@return any
local function field(node, key, default)
  if type(node) ~= "table" then
    return default
  end
  local v = node[key]
  if v == nil or v == json.null then
    return default
  end
  return v
end

---@return table manifest
local cached_manifest
local function manifest()
  if cached_manifest then
    return cached_manifest
  end
  local fh, err = io.open(CASES_JSON, "r")
  if not fh then
    error(
      "consistency manifest not found at "
        .. CASES_JSON
        .. " ("
        .. tostring(err)
        .. "). Run `python tests/consistency/generate_cases.py` to"
        .. " generate it.",
      0
    )
  end
  local content = fh:read("*a")
  fh:close()
  local decoded, decode_err = json.decode(content)
  assert(
    decoded,
    "failed to decode " .. CASES_JSON .. ": " .. tostring(decode_err)
  )
  assert(
    field(decoded, "version", nil) == 1,
    "unsupported consistency manifest version: "
      .. tostring(field(decoded, "version", nil))
  )
  cached_manifest = decoded
  return cached_manifest
end

---@param name string
---@return table
local function find_case(name)
  for _, case in ipairs(field(manifest(), "cases", {})) do
    if field(case, "name", nil) == name then
      return case
    end
  end
  error("consistency case not found in manifest: " .. name, 0)
end

---The RPC surface of the core this binding is linked against, as a set,
---resolved once per run. Cores that predate `BuiltinService.ListMethod`
---answer with an empty list or raise; either way `new_core` cases are skipped
---rather than failed.
---@return table<string, boolean>
local available_methods
local function methods()
  if available_methods then
    return available_methods
  end
  local set = {}
  local ok, result = pcall(api.list_method, api, {})
  if ok then
    for _, name in ipairs(field(result, "method_name_list", {})) do
      set[name] = true
    end
  end
  available_methods = set
  return available_methods
end

-- The marker `generate_cases.py` writes into a path that names a template
-- rather than a file. `scratch:a/b.k` means "b.k inside a copy of
-- testdata/a"; the copy is what makes the RPCs that write files safe to run,
-- and it is also why the expectations for those cases pin the RPC's answer
-- rather than a path.
local SCRATCH_PREFIX = "scratch:"

---The scratch directories this run created, newest last. Each entry is the
---root of one copy; `cleanup_scratch` takes the whole list down with the case
---that made it, so a run leaves nothing for the next one.
---@type table
local scratch_dirs = {}

---Recursively delete `path`. The scratch tree only ever holds copies this
---runner made, so a plain recursive delete is enough.
---@param path string
local function remove_tree(path)
  for entry in lfs.dir(path) do
    if entry ~= "." and entry ~= ".." then
      local child = pl_path.join(path, entry)
      if lfs.attributes(child, "mode") == "directory" then
        remove_tree(child)
      else
        assert(os.remove(child), "failed to remove scratch file " .. child)
      end
    end
  end
  assert(os.remove(path), "failed to remove scratch directory " .. path)
end

---@param src string
---@param dest string
local function copy_tree(src, dest)
  local made, make_err = lfs.mkdir(dest)
  assert(made, "failed to create " .. dest .. ": " .. tostring(make_err))
  for entry in lfs.dir(src) do
    if entry ~= "." and entry ~= ".." then
      local from = pl_path.join(src, entry)
      local to = pl_path.join(dest, entry)
      if lfs.attributes(from, "mode") == "directory" then
        copy_tree(from, to)
      else
        -- A real copy rather than a hard link: `KclService.OverrideFile`
        -- writes through the path it was handed, and a link would send that
        -- write back into the repository.
        local input = assert(io.open(from, "rb"), "failed to read " .. from)
        local output = assert(io.open(to, "wb"), "failed to write " .. to)
        local body = input:read("*a")
        input:close()
        assert(output:write(body), "failed to write " .. to)
        output:close()
      end
    end
  end
end

---Copy `testdata/<template>` with `pl.path`/`lfs` and return the path of
---`tail` inside the copy. Each call gets its own directory, so two cases --
---and two runs -- never observe each other's writes and the repository is
---never the target of an RPC that rewrites files. Note that a case naming the
---same template twice (`load_settings_files` names one in both `work_dir` and
---`files`) gets two copies, exactly as the python, java and zig runners do.
---@param rest string
---@return string
local function scratch(rest)
  -- `/?` is not a capture, so this yields the template and the tail alone.
  local template, tail = rest:match("^([^/]*)/?(.*)$")
  local src = pl_path.join(TESTDATA, template)
  assert(
    lfs.attributes(src, "mode") == "directory",
    "scratch template is not a directory: " .. src
  )
  local root = os.tmpname()
  -- `os.tmpname` may hand back the name of a file it already created, and
  -- `lfs.mkdir` needs the name free. The removal is best effort by design;
  -- the `mkdir` below is the check that matters.
  os.remove(root)
  local made, make_err = lfs.mkdir(root)
  assert(
    made,
    "failed to create scratch directory " .. root .. ": " .. tostring(make_err)
  )
  scratch_dirs[#scratch_dirs + 1] = root
  local dest = pl_path.join(root, template)
  copy_tree(src, dest)
  return tail ~= "" and pl_path.join(dest, tail) or dest
end

---Delete every scratch copy made so far. Wired into every case through
---`finally`, so it runs whether or not the case passed.
local function cleanup_scratch()
  for i = #scratch_dirs, 1, -1 do
    remove_tree(scratch_dirs[i])
  end
  scratch_dirs = {}
end

---Resolve one manifest path entry: a `scratch:` marker, an absolute path, or
---a repo-relative one (the manifest pins those relative to the repository
---root; absolute entries are kept as-is).
---@param p string
---@return string
local function resolve_path(p)
  if p:sub(1, #SCRATCH_PREFIX) == SCRATCH_PREFIX then
    return scratch(p:sub(#SCRATCH_PREFIX + 1))
  end
  if pl_path.isabs(p) then
    return p
  end
  return pl_path.join(REPO_ROOT, p)
end

---Resolve a manifest list of path entries.
---@param values any
---@return table
local function resolve_paths(values)
  local out = {}
  for i, p in ipairs(values or {}) do
    out[i] = resolve_path(p)
  end
  return out
end

---Build `ParseProgramArgs` from the manifest, and the args of the RPCs that
---take one directly (`ParseProgram` and `ListOptions`) or nest one
---(`GenerateOpenAPI`, `GenerateProto`, `GenerateDoc`, `LoadPackage`).
---@param node table
---@return table
local function parse_args(node)
  local args = {}
  local paths = resolve_paths(field(node, "paths", {}))
  if #paths > 0 then
    args.paths = paths
  end
  local sources = field(node, "sources", nil)
  if sources then
    args.sources = sources
  end
  local external_pkgs = field(node, "external_pkgs", nil)
  if external_pkgs then
    args.external_pkgs = external_pkgs
  end
  return args
end

---Build `ExecProgramArgs` from the manifest. The manifest spells out every
---proto3 field, but the unset ones carry their proto defaults, so only the
---fields that actually drive the case are forwarded.
---
---`k_filename_list` is resolved by the core against the process working
---directory rather than against `work_dir`, so a relative entry has to be
---made absolute here or it will not survive being run from another directory.
---@param node table
---@return table
local function exec_args(node)
  local args = {}
  local work_dir = field(node, "work_dir", nil)
  local resolved_dir = work_dir and resolve_path(work_dir) or "."
  for _, key in ipairs({
    "k_code_list",
    "overrides",
    "disable_yaml_result",
    "print_override_ast",
    "strict_range_check",
    "disable_none",
    "sort_keys",
    "include_schema_type_path",
    "compile_only",
    "show_hidden",
    "path_selector",
    "fast_eval",
    "error_format",
    "format",
    "emit_attribute_metadata",
    "verbose",
    "debug",
  }) do
    local v = field(node, key, nil)
    if v ~= nil and v ~= "" then
      args[key] = v
    end
  end
  if work_dir then
    args.work_dir = resolved_dir
  end
  local filenames = field(node, "k_filename_list", nil)
  if filenames and #filenames > 0 then
    local resolved = {}
    for i, name in ipairs(filenames) do
      resolved[i] = pl_path.isabs(name) and name
        or pl_path.join(resolved_dir, name)
    end
    args.k_filename_list = resolved
  end
  -- `args` is a `repeated Argument`, not a `repeated string`.
  local arguments = {}
  for _, spec in ipairs(field(node, "args", {})) do
    local name, value = spec:match("^([^=]*)=(.*)$")
    if name then
      arguments[#arguments + 1] = { name = name, value = value }
    end
  end
  if #arguments > 0 then
    args.args = arguments
  end
  local external_pkgs = field(node, "external_pkgs", nil)
  if external_pkgs and #external_pkgs > 0 then
    args.external_pkgs = external_pkgs
  end
  return args
end

---`ParseFileArgs`. Unlike `ParseProgramArgs.paths`, `path` is a label the AST
---records rather than a file to read -- `source` carries the program -- so it
---is forwarded verbatim.
---@param node table
---@return table
local function parse_file_args(node)
  local args = {}
  for _, key in ipairs({ "path", "source" }) do
    args[key] = field(node, key, "")
  end
  local external_pkgs = field(node, "external_pkgs", nil)
  if external_pkgs and #external_pkgs > 0 then
    args.external_pkgs = external_pkgs
  end
  return args
end

---@return table
local function validate_args(node)
  local args = {}
  for _, key in ipairs({
    "code",
    "data",
    "datafile",
    "file",
    "schema",
    "attribute_name",
    "format",
  }) do
    local v = field(node, key, nil)
    if v ~= nil and v ~= "" then
      args[key] = v
    end
  end
  local external_pkgs = field(node, "external_pkgs", nil)
  if external_pkgs and #external_pkgs > 0 then
    args.external_pkgs = external_pkgs
  end
  return args
end

---The shared shape of both schema-mapping request builders.
---@param node table
---@return table
local function schema_args(node)
  return {
    exec_args = exec_args(field(node, "exec_args", {})),
    schema_name = field(node, "schema_name", ""),
  }
end

---The manifest spells `TestCaseInfo.duration` as a decimal string because JSON
---numbers cannot hold a `uint64` microsecond count portably.
---@param value any
---@return integer
local function uint64(value)
  if type(value) == "string" then
    return tonumber(value, 10) or 0
  end
  return value or 0
end

---Build `TestResult` from the manifest.
---@param node table
---@return table
local function test_result(node)
  local info = {}
  for _, entry in ipairs(field(node, "info", {})) do
    info[#info + 1] = {
      name = field(entry, "name", ""),
      error = field(entry, "error", ""),
      duration = uint64(field(entry, "duration", 0)),
      log_message = field(entry, "log_message", ""),
    }
  end
  return { info = info }
end

---Number of entries in a decoded protobuf field. `lua-protobuf` hands a
---`repeated` field back as a 1-based array and a `map` field as a table keyed
---by the encoded key, so `#` only counts the former -- `LoadPackage.symbols`
---has 20 entries and length zero.
---@param value any
---@return integer
local function count(value)
  if type(value) ~= "table" then
    return 0
  end
  local n = 0
  for _ in pairs(value) do
    n = n + 1
  end
  return n
end

---Count the entries of `key` (optionally `key.subkey`) in a JSON document,
---treating an empty or unparsable document as zero. `ParseFile` answers a
---bare `Module` -- the statements are at `body` -- while `ParseProgram` answers
---a `pkgs` document keyed by package path, so the two count different paths
---into the same tree.
---@param doc string|nil
---@param key string
---@param subkey string|nil
---@return integer
local function count_array(doc, key, subkey)
  if type(doc) ~= "string" or doc == "" then
    return 0
  end
  local decoded = json.decode(doc)
  if type(decoded) ~= "table" then
    return 0
  end
  local node = field(decoded, key, nil)
  if subkey then
    node = field(node, subkey, nil)
  end
  return count(node)
end

---Canonical JSON for a projected value: every object key sorted and the
---`filename` key dropped. `KclType` holds two protobuf map fields whose
---iteration order is undefined, and `filename` is an absolute path that
---differs on every machine, so neither can be compared as it arrives. An empty
---table renders as `{}`, which is what an empty array and an empty object both
---decode to on the manifest side, so the two still agree.
---@param value any
---@return string
local function canonical_json(value)
  if type(value) ~= "table" then
    -- `dkjson` decodes every JSON number as a float; render the integral ones
    -- without a fractional part so `line = 2` never becomes `2.0`.
    if type(value) == "number" and value == math.floor(value) then
      return string.format("%d", value)
    end
    return json.encode(value)
  end
  if #value > 0 then
    local items = {}
    for i, item in ipairs(value) do
      items[i] = canonical_json(item)
    end
    return "[" .. table.concat(items, ",") .. "]"
  end
  local keys = {}
  for key in pairs(value) do
    keys[#keys + 1] = key
  end
  table.sort(keys)
  local parts = {}
  for _, key in ipairs(keys) do
    if key ~= "filename" then
      parts[#parts + 1] = json.encode(key) .. ":" .. canonical_json(value[key])
    end
  end
  return "{" .. table.concat(parts, ",") .. "}"
end

---The rendering a pinned field is compared through, so both sides of every
---comparison go through one definition of the canonical form. A top-level
---string stays raw: the generated documents are dozens of lines long, and the
---mismatch report diffs them line by line.
---@param value any
---@return string
local function render(value)
  if type(value) == "string" then
    return value
  end
  return canonical_json(value)
end

---Split on newlines the way `split("\n", -1)` does, trailing empty line and
---all.
---@param text string
---@return table
local function split_lines(text)
  local out = {}
  for line in (text .. "\n"):gmatch("(.-)\n") do
    out[#out + 1] = line
  end
  return out
end

---Line-wise `--- expected / +++ actual` rendering, mirroring the java and zig
---runners so a golden mismatch reads the same in every language.
---@param expected string
---@param actual string
---@return string
local function diff(expected, actual)
  local want, got = split_lines(expected), split_lines(actual)
  local out = { "--- expected", "+++ actual" }
  for i = 1, math.max(#want, #got) do
    local e, a = want[i], got[i]
    if e == a then
      out[#out + 1] = "  " .. e
    else
      if e ~= nil then
        out[#out + 1] = "- " .. e
      end
      if a ~= nil then
        out[#out + 1] = "+ " .. a
      end
    end
  end
  return table.concat(out, "\n")
end

---A `KclType` as canonical protobuf JSON -- the *default* dialect, so a field
---the core left unset is absent rather than rendered as an empty value.
---Written out by hand because `lua-protobuf` fills every field in with its
---proto default (`""`, `0`, `[]`) whether or not it was set, and the golden
---file is the default dialect too: a pass-through would disagree with every
---other runner on every schema.
---@param ty table|nil
---@return table
local function kcl_type_json(ty)
  local out = {}
  if type(ty) ~= "table" then
    return out
  end
  -- `filename` is emitted here and dropped by `canonical_json`, so there is
  -- exactly one place that decides an unpinnable field is dropped.
  for _, key in ipairs({
    "type",
    "schema_name",
    "schema_doc",
    "default",
    "pkg_path",
    "description",
    "filename",
  }) do
    if ty[key] ~= nil and ty[key] ~= "" then
      out[key] = ty[key]
    end
  end
  if ty.line ~= nil and ty.line ~= 0 then
    out.line = ty.line
  end
  if ty.required and #ty.required > 0 then
    out.required = ty.required
  end
  if ty.union_types and #ty.union_types > 0 then
    local items = {}
    for i, child in ipairs(ty.union_types) do
      items[i] = kcl_type_json(child)
    end
    out.union_types = items
  end
  if ty.properties and count(ty.properties) > 0 then
    local map = {}
    for name, child in pairs(ty.properties) do
      map[name] = kcl_type_json(child)
    end
    out.properties = map
  end
  if ty.examples and count(ty.examples) > 0 then
    local map = {}
    for name, child in pairs(ty.examples) do
      local example = {}
      for _, key in ipairs({ "summary", "description", "value" }) do
        if child[key] ~= nil and child[key] ~= "" then
          example[key] = child[key]
        end
      end
      map[name] = example
    end
    out.examples = map
  end
  if ty.decorators and #ty.decorators > 0 then
    local items = {}
    for i, decorator in ipairs(ty.decorators) do
      local entry = {}
      if decorator.name ~= nil and decorator.name ~= "" then
        entry.name = decorator.name
      end
      if decorator.arguments and #decorator.arguments > 0 then
        entry.arguments = decorator.arguments
      end
      if decorator.keywords and count(decorator.keywords) > 0 then
        entry.keywords = decorator.keywords
      end
      items[i] = entry
    end
    out.decorators = items
  end
  if type(ty.key) == "table" then
    out.key = kcl_type_json(ty.key)
  end
  if type(ty.item) == "table" then
    out.item = kcl_type_json(ty.item)
  end
  if type(ty.base_schema) == "table" then
    out.base_schema = kcl_type_json(ty.base_schema)
  end
  -- `function` and `index_signature` are proto3 `optional`, so `lua-protobuf`
  -- leaves them nil when unset -- the same "absent, not empty" the default
  -- JSON dialect asks for.
  local func = ty["function"]
  if type(func) == "table" then
    local entry = {}
    if func.params and #func.params > 0 then
      local items = {}
      for i, param in ipairs(func.params) do
        local rendered = {}
        if param.name ~= nil and param.name ~= "" then
          rendered.name = param.name
        end
        if type(param.ty) == "table" then
          rendered.ty = kcl_type_json(param.ty)
        end
        items[i] = rendered
      end
      entry.params = items
    end
    if type(func.return_ty) == "table" then
      entry.return_ty = kcl_type_json(func.return_ty)
    end
    out["function"] = entry
  end
  if type(ty.index_signature) == "table" then
    local sig = ty.index_signature
    local entry = {}
    if sig.key_name ~= nil and sig.key_name ~= "" then
      entry.key_name = sig.key_name
    end
    if type(sig.key) == "table" then
      entry.key = kcl_type_json(sig.key)
    end
    if type(sig.val) == "table" then
      entry.val = kcl_type_json(sig.val)
    end
    if sig.any_other then
      entry.any_other = true
    end
    out.index_signature = entry
  end
  return out
end

---`GetSchemaTypeMappingUnderPath` answers a `SchemaTypes` document -- a
---`schema_type` array rather than the flat map the plain RPC returns -- so the
---two cases serialise through different shapes even though the runner pins
---both under `type_mapping`.
---@param sty table|nil
---@return table
local function schema_types_json(sty)
  local out = { schema_type = {} }
  if type(sty) ~= "table" then
    return out
  end
  for i, ty in ipairs(sty.schema_type or {}) do
    out.schema_type[i] = kcl_type_json(ty)
  end
  return out
end

---@param mapping table|nil
---@param project fun(value: table): table
---@return table
local function type_mapping(mapping, project)
  local out = {}
  for name, value in pairs(mapping or {}) do
    out[name] = project(value)
  end
  return out
end

---A `[[a, b], ...]` list of pairs, sorted on the first element. The order the
---core answers with is not pinnable -- a protobuf map's iteration order is
---undefined -- so the manifest pins these as a set.
---@param pairs_list table
---@return table
local function sort_pairs(pairs_list)
  local out = {}
  for i, pair in ipairs(pairs_list) do
    out[i] = { pair[1], pair[2] }
  end
  table.sort(out, function(a, b)
    return a[1] < b[1]
  end)
  return out
end

---@param values any
---@param project fun(value: string): string
---@return table
local function sorted_basenames(values, project)
  local out = {}
  for i, p in ipairs(values or {}) do
    out[i] = project(p)
  end
  table.sort(out)
  return out
end

---Per-case projections, mirroring the `extract` of each definition in
---`tests/consistency/generate_cases.py`. A case reads every field its `expect`
---block names off the table its RPC returns; the cases whose contract is a
---shape or a count rather than a top-level field compute one here.
---@return table<string, function> dispatch
local function dispatch()
  return {
    ["KclService.Ping"] = function(case)
      local result = api:ping({ value = field(case.args, "value", "") })
      return { value = result.value }
    end,
    ["KclService.ExecProgram"] = function(case)
      local result = api:exec_program(exec_args(case.args))
      return {
        yaml_result = result.yaml_result,
        json_result = result.json_result,
      }
    end,
    ["KclService.FormatCode"] = function(case)
      local result = api:format_code({
        source = field(case.args, "source", ""),
      })
      return { formatted = result.formatted }
    end,
    ["KclService.ValidateCode"] = function(case)
      local result = api:validate_code(validate_args(case.args))
      return {
        success = result.success == true,
        -- The diagnostic carries ANSI colour escapes, a random temp path and a
        -- temp filename, so the string itself is not pinnable but its
        -- presence is. `err_message` is emitted for both cases so
        -- `validate_code_ok`, which pins it as the empty string, still finds
        -- the field the manifest names.
        has_error_message = (result.err_message or "") ~= "",
        err_message = result.err_message or "",
      }
    end,
    ["KclService.FormatTestReport"] = function(case)
      local result = api:format_test_report({
        result = test_result(field(case.args, "result", {})),
      })
      return { report = result.report }
    end,
    ["KclService.GenerateToml"] = function(case)
      local result = api:generate_toml({
        exec_args = exec_args(field(case.args, "exec_args", {})),
        sort_keys = field(case.args, "sort_keys", false),
      })
      return { toml = result.toml }
    end,
    ["KclService.GenerateKcl"] = function(case)
      local result = api:generate_kcl({
        source = field(case.args, "source", ""),
        filename = field(case.args, "filename", ""),
        format = field(case.args, "format", ""),
      })
      return { kcl = result.kcl }
    end,
    ["KclService.GenerateOpenAPI"] = function(case)
      local result = api:generate_openapi({
        parse_args = parse_args(field(case.args, "parse_args", {})),
        version = field(case.args, "version", ""),
      })
      return { spec = result.spec }
    end,
    ["KclService.GenerateProto"] = function(case)
      local result = api:generate_proto({
        parse_args = parse_args(field(case.args, "parse_args", {})),
        package = field(case.args, "package", ""),
      })
      return { proto = result.proto }
    end,
    ["KclService.GenerateDoc"] = function(case)
      local result = api:generate_doc({
        parse_args = parse_args(field(case.args, "parse_args", {})),
        format = field(case.args, "format", ""),
      })
      return { content = result.content }
    end,
    ["KclService.ParseFile"] = function(case)
      local result = api:parse_file(parse_file_args(case.args))
      return {
        -- A bare `Module` document, so the statements are at `body`.
        body_count = count_array(result.ast_json, "body"),
        error_count = count(result.errors),
        deps = result.deps or {},
      }
    end,
    ["KclService.ParseProgram"] = function(case)
      local result = api:parse_program(parse_args(case.args))
      return {
        -- `ParseProgram` returns a `pkgs` document, not a module: one Module
        -- per file, keyed by package path.
        module_count = count_array(result.ast_json, "pkgs", "__main__"),
        error_count = count(result.errors),
        paths = sorted_basenames(result.paths, pl_path.basename),
      }
    end,
    ["KclService.ListOptions"] = function(case)
      local result = api:list_options(parse_args(case.args))
      local options = {}
      for i, option in ipairs(result.options or {}) do
        options[i] = { option.name, option.required == true }
      end
      return {
        option_count = count(result.options),
        options = sort_pairs(options),
      }
    end,
    ["KclService.ListVariables"] = function(case)
      local result = api:list_variables({
        files = resolve_paths(field(case.args, "files", {})),
        specs = field(case.args, "specs", {}),
        options = {
          merge_program =
            field(field(case.args, "options", {}), "merge_program", false),
        },
      })
      local values = {}
      for spec, list in pairs(result.variables or {}) do
        local items = {}
        for i, variable in ipairs(list.variables or {}) do
          items[i] = variable.value
        end
        values[spec] = items
      end
      return {
        values = values,
        unsupported_codes = result.unsupported_codes or {},
        parse_error_count = count(result.parse_errors),
      }
    end,
    ["KclService.LoadPackage"] = function(case)
      local result = api:load_package({
        parse_args = parse_args(field(case.args, "parse_args", {})),
        resolve_ast = field(case.args, "resolve_ast", false),
        load_builtin = field(case.args, "load_builtin", false),
        with_ast_index = field(case.args, "with_ast_index", false),
      })
      local mod = result.kcl_mod
      local has_mod = type(mod) == "table"
      return {
        path_count = count(result.paths),
        type_error_count = count(result.type_errors),
        parse_error_count = count(result.parse_errors),
        symbol_count = count(result.symbols),
        scope_count = count(result.scopes),
        has_kcl_mod = has_mod,
        kcl_mod_name = has_mod and type(mod.package) == "table"
          and mod.package.name
          or "",
        app_count = count(result.apps),
        import_count = count(result.imports),
      }
    end,
    ["KclService.GetSchemaTypeMapping"] = function(case)
      local result = api:get_schema_type_mapping(schema_args(case.args))
      return {
        type_mapping = type_mapping(
          result.schema_type_mapping,
          kcl_type_json
        ),
      }
    end,
    ["KclService.GetSchemaTypeMappingUnderPath"] = function(case)
      local result = api:get_schema_type_mapping_under_path(
        schema_args(case.args)
      )
      return {
        type_mapping = type_mapping(
          result.schema_type_mapping,
          schema_types_json
        ),
      }
    end,
    ["KclService.GetVersion"] = function()
      local result = api:get_version({})
      -- Only the major.minor pair is pinned: the patch moves with every
      -- release, and the manifest is regenerated against a pinned core.
      local parts = {}
      for part in tostring(result.version or ""):gmatch("[^%.]+") do
        parts[#parts + 1] = part
      end
      local version = #parts >= 2 and (parts[1] .. "." .. parts[2])
        or (result.version or "")
      return {
        version = version,
        has_checksum = (result.checksum or "") ~= "",
        has_git_sha = (result.git_sha or "") ~= "",
        has_version_info = (result.version_info or "") ~= "",
      }
    end,
    ["BuiltinService.ListMethod"] = function()
      local result = api:list_method({})
      local names = result.method_name_list or {}
      local listed, empty = {}, false
      for _, name in ipairs(names) do
        listed[name] = true
        if name == "" then
          empty = true
        end
      end
      return {
        has_kclservice_ping = listed["KclService.Ping"] == true,
        has_kclservice_parse_program =
          listed["KclService.ParseProgram"] == true,
        has_builtinservice_list_method =
          listed["BuiltinService.ListMethod"] == true,
        method_count = count(names),
        has_empty_name = empty,
      }
    end,
    ["KclService.LintPath"] = function(case)
      local result = api:lint_path({
        paths = resolve_paths(field(case.args, "paths", {})),
      })
      return {
        result_count = count(result.results),
        has_result = count(result.results) > 0,
      }
    end,
    ["KclService.FormatPath"] = function(case)
      local result = api:format_path({
        path = resolve_path(field(case.args, "path", "")),
        dry_run = field(case.args, "dry_run", false),
      })
      return {
        changed_count = count(result.changed_paths),
        changed = sorted_basenames(result.changed_paths, pl_path.basename),
      }
    end,
    ["KclService.Test"] = function(case)
      local result = api:test({
        exec_args = exec_args(field(case.args, "exec_args", {})),
        pkg_list = resolve_paths(field(case.args, "pkg_list", {})),
        run_regexp = field(case.args, "run_regexp", ""),
        fail_fast = field(case.args, "fail_fast", false),
        coverage = field(case.args, "coverage", false),
      })
      local names, failed = {}, {}
      for _, info in ipairs(result.info or {}) do
        names[#names + 1] = info.name
        if (info.error or "") ~= "" then
          failed[#failed + 1] = info.name
        end
      end
      table.sort(names)
      table.sort(failed)
      return { names = names, failed = failed }
    end,
    ["KclService.OverrideFile"] = function(case)
      local result = api:override_file({
        file = resolve_path(field(case.args, "file", "")),
        specs = field(case.args, "specs", {}),
        import_paths = resolve_paths(field(case.args, "import_paths", {})),
      })
      return {
        result = result.result == true,
        parse_error_count = count(result.parse_errors),
      }
    end,
    ["KclService.LoadSettingsFiles"] = function(case)
      local result = api:load_settings_files({
        work_dir = resolve_path(field(case.args, "work_dir", "")),
        files = resolve_paths(field(case.args, "files", {})),
      })
      local options = {}
      for i, option in ipairs(result.kcl_options or {}) do
        options[i] = { option.key, option.value }
      end
      local out = { options = sort_pairs(options) }
      local config = result.kcl_cli_configs
      if type(config) == "table" then
        out.output = config.output or ""
        out.overrides = config.overrides or {}
        out.strict_range_check = config.strict_range_check == true
        out.verbose = config.verbose or 0
      end
      return out
    end,
    ["KclService.UpdateDependencies"] = function(case)
      local result = api:update_dependencies({
        manifest_path = resolve_path(field(case.args, "manifest_path", "")),
        vendor = field(case.args, "vendor", false),
      })
      return { external_pkg_count = count(result.external_pkgs) }
    end,
  }
end

---Run one manifest case: dispatch on `rpc`, then compare every field that
---`expect` actually mentions. Unknown RPCs are a hard failure, a missing RPC
---on an old core is a skip.
---@param name string
local function run_case(name)
  local case = find_case(name)
  local rpc = field(case, "rpc", "")
  local project = dispatch()[rpc]
  assert.is_true(project ~= nil, "no runner support for rpc " .. tostring(rpc))

  if field(case, "new_core", false) and not methods()[rpc] then
    pending("core does not list " .. rpc .. " (old core)")
    return
  end

  local actual = project(case)
  local expect = field(case, "expect", {})
  -- Compare exactly the fields the manifest pins down, sorted so that a
  -- multi-field mismatch always reports the same one first.
  local keys = {}
  for key in pairs(expect) do
    keys[#keys + 1] = key
  end
  table.sort(keys)
  assert.is_true(#keys > 0, "consistency case `" .. name .. "` pins no fields")
  for _, key in ipairs(keys) do
    -- Only the fields the manifest pins are compared, so adding a field to
    -- `expect` is the only way to start asserting on it. A projection may
    -- compute more than that, but a pinned field the projection does not
    -- produce is a failure rather than a skip, because the key is missing
    -- from the projection either way.
    assert.is_true(
      actual[key] ~= nil,
      "consistency case `" .. name .. "` expects field `" .. key
        .. "`, which the projection does not produce"
    )
    local want, got = render(expect[key]), render(actual[key])
    assert.are.equal(
      want,
      got,
      string.format(
        "consistency case `%s` field `%s` mismatch\n%s",
        name,
        key,
        diff(want, got)
      )
    )
  end
end

describe("consistency", function()
  ---Every case in `tests/consistency/cases.json`, dispatched by the loop
  ---below. Hand-maintained rather than read back from what the suite actually
  ---ran: a check that inferred its own coverage would agree with itself,
  ---which is the opposite of a check.
  local case_names = {
    "ping",
    "exec_program_basic",
    "exec_program_overrides",
    "format_code",
    "validate_code_ok",
    "validate_code_invalid",
    "generate_kcl_json",
    "generate_kcl_yaml",
    "generate_toml",
    "format_test_report",
    "generate_openapi_v3",
    "generate_proto",
    "generate_doc_md",
    "parse_file",
    "parse_program",
    "list_options",
    "list_variables",
    "load_package",
    "get_schema_type_mapping",
    "get_schema_type_mapping_under_path",
    "get_version",
    "list_method",
    "lint_path_clean",
    "lint_path_with_errors",
    "format_path_dry_run",
    "test_run",
    "override_file",
    "load_settings_files",
    "update_dependencies_no_deps",
  }

  for _, name in ipairs(case_names) do
    it(name, function()
      -- `finally` rather than `teardown`: busted only offers `teardown` on a
      -- context block, and this has to wrap the case itself so a failing case
      -- still cleans its scratch copies up instead of leaving them behind.
      finally(cleanup_scratch)
      run_case(name)
    end)
  end

  -- Every case in the manifest must be dispatched by one of the `it` blocks
  -- above. Without this a runner that covers half the spec passes silently,
  -- which is exactly how the manifest could grow from 13 cases to 29 while
  -- this file still ran only 13. The check reads `case_names` rather than
  -- anything the suite recorded at run time, so it does not depend on
  -- ordering and cannot agree with itself; it is declared last anyway so a
  -- half-covered manifest is reported on a run that is otherwise green.
  it("dispatches every case in the manifest", function()
    local missing = {}
    for _, case in ipairs(field(manifest(), "cases", {})) do
      local name = field(case, "name", "")
      local found = false
      for _, dispatched in ipairs(case_names) do
        if dispatched == name then
          found = true
          break
        end
      end
      if not found then
        missing[#missing + 1] = name
      end
    end
    table.sort(missing)
    assert.are.same(
      {},
      missing,
      "cases.json has cases this runner does not dispatch; add an `it` for each"
    )
  end)
end)
